function boundedXRange(gtlt: string, major: number, minor: number, xMinor = minor === 0): string {
  if (gtlt === ">") {
    return xMinor ? `>=${major + 1}.0.0` : `>=${major}.${minor + 1}.0`;
  }
  if (gtlt === "<=") {
    return xMinor ? `<${major + 1}.${minor}.0-0` : `<${major}.${minor + 1}.0-0`;
  }
  if (gtlt === "<") return `<${major}.${minor}.0-0`;
  return `${gtlt}${major}.${minor}.0`;
}

edits.newText:
// `>1.2` means `>=1.3.0`, `<=1.2` means `<1.3.0-0`, `<1.2` means `<1.2.0-0`.
function boundedXRange(gtlt: string, major: number, minor: number, xMinor: boolean): string {
  const [lowMajor, lowMinor] = xMinor ? [major, 0] : [major, minor];
  const [nextMajor, nextMinor] = xMinor ? [major + 1, 0] : [major, minor + 1];
  if (gtlt === ">") return `>=${nextMajor}.${nextMinor}.0`;
  if (gtlt === "<=") return `<${nextMajor}.${nextMinor}.0-0`;
  if (gtlt === "<") return `<${lowMajor}.${lowMinor}.0-0`;
  return `${gtlt}${lowMajor}.${lowMinor}.0`;
}

